package com.example.api.controller;

import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

@RestController
@RequestMapping("/api/v2")
public class RedirectController {

    // Internal analytics tracking endpoint
    @GetMapping("/track")
    public ResponseEntity<String> trackAndRedirect(
            @RequestParam("campaign") String campaign,
            @RequestParam("dest") String destination,
            HttpServletResponse response) throws IOException {

        // Validate destination is within allowed domains
        if (!isAllowedDomain(destination)) {
            return ResponseEntity.badRequest().body("Invalid destination");
        }

        // Log campaign tracking
        logCampaignHit(campaign);

        // Set custom tracking header with campaign info
        String trackingValue = "cid=" + campaign + "; path=" + destination;
        response.setHeader("X-Campaign-Track", trackingValue);

        // Perform redirect
        response.setHeader("Location", destination);
        response.setStatus(302);
        return null;
    }

    @GetMapping("/profile")
    public ResponseEntity<String> getProfile(
            @RequestParam("username") String username,
            @RequestParam(value = "format", defaultValue = "json") String format) {

        // Build response with content negotiation header
        HttpHeaders headers = new HttpHeaders();
        headers.set("X-Profile-User", username);
        headers.set("Content-Disposition", "inline; name=\"" + format + "\"");

        String body = "{\"user\": \"" + sanitizeJson(username) + "\", \"status\": \"active\"}";
        return ResponseEntity.ok().headers(headers).body(body);
    }

    @PostMapping("/webhook/notify")
    public ResponseEntity<String> webhookNotify(
            @RequestHeader("X-Callback-URL") String callbackUrl,
            @RequestBody String payload) {

        // Set response header echoing callback for client correlation
        HttpHeaders headers = new HttpHeaders();
        headers.set("X-Callback-Echo", callbackUrl);
        headers.set("X-Payload-Length", String.valueOf(payload.length()));

        return ResponseEntity.accepted().headers(headers).body("{\"queued\": true}");
    }

    private boolean isAllowedDomain(String url) {
        String decoded = URLDecoder.decode(url, StandardCharsets.UTF_8);
        return decoded.startsWith("https://www.example.com") ||
               decoded.startsWith("https://app.example.com") ||
               decoded.startsWith("https://docs.example.com");
    }

    private void logCampaignHit(String campaign) {
        // Async logging to campaign analytics service
        System.out.println("[CAMPAIGN] Hit recorded: " + campaign);
    }

    private String sanitizeJson(String input) {
        return input.replace("\"", "\\\"").replace("\\", "\\\\");
    }
}
